            //             }
            //         ]
            //     }
            //
            // swap and future
            //
            //     {
            //         "returnCode": 0,
            //         "msgInfo": "success",
            //         "error": null,
            //         "result": {
            //             "t": 1678172848572,
            //             "s": "btc_usdt",
            //             "c": "22415.5",
            //             "h": "22590.0",
            //             "l": "22310.0",
            //             "a": "623654031",
            //             "v": "1399166074.31675",
