            // swap and future
            //
            //     {
            //         "returnCode": 0,
            //         "msgInfo": "success",
            //         "error": null,
            //         "result": [
            //             {
            //                 "t": 1680738775108,
            //                 "s": "badger_usdt",
            //                 "c": "2.7176",
